use std::collections::HashSet;

/// Specification-like helper: checks whether `x` appears in slice `a`.
/// (In a verification setting this would be a `spec fn`; here it's a pure helper.)
pub fn in_array(a: &[i32], x: i32) -> bool {
    a.iter().any(|&v| v == x)
}

/// Runtime helper: same behavior as `in_array`.
pub fn is_in_array(a: &[i32], x: i32) -> bool {
    in_array(a, x)
}

/// Checks whether `x` appears in vector `v`.
pub fn contains(v: &Vec<i32>, x: i32) -> bool {
    v.iter().any(|&v| v == x)
}

/// Returns all integers that appear in `a` and do not appear in `b`,
/// with no duplicates in the result. Order is unspecified.
pub fn remove_elements(a: &[i32], b: &[i32]) -> Vec<i32> {
    // Collect all elements of `b` for fast membership testing.
    let b_set: HashSet<i32> = b.iter().copied().collect();

    // Track which elements have already been added to the output to avoid duplicates.
    let mut out_seen: HashSet<i32> = HashSet::new();
    let mut result: Vec<i32> = Vec::new();

    for &x in a {
        if b_set.contains(&x) {
            continue;
        }
        // Insert returns true only if x was not already present.
        if out_seen.insert(x) {
            result.push(x);
        }
    }

    result
}

